package com.skillbankorganizer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("skillbankorganizer")
public interface SkillBankOrganizerConfig extends Config
{
	@ConfigItem(
		keyName = "autoScan",
		name = "Scan when bank opens",
		description = "Refresh the skill pages whenever your bank contents change.",
		position = 0
	)
	default boolean autoScan()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includePlaceholders",
		name = "Include placeholders",
		description = "Count placeholder slots as items you own (quantity 0).",
		position = 1
	)
	default boolean includePlaceholders()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hideEmptySkills",
		name = "Hide empty skills",
		description = "Hide skill pages that currently have nothing in the bank.",
		position = 2
	)
	default boolean hideEmptySkills()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showChatScan",
		name = "Chat message on scan",
		description = "Write a game-message when a bank scan finishes.",
		position = 3
	)
	default boolean showChatScan()
	{
		return false;
	}

	@ConfigItem(
		keyName = "rightClickSend",
		name = "Right-click: Send to page",
		description = "Add a Send-to-page option on bank items. Plugins cannot drag items; this opens the page and tags it.",
		position = 4
	)
	default boolean rightClickSend()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tagOnSend",
		name = "Tag item on Send",
		description = "Write a Bank Tags tag (e.g. #woodcutting) so you can filter that skill in the bank.",
		position = 5
	)
	default boolean tagOnSend()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightPage",
		name = "Highlight current page in bank",
		description = "Draw a border on bank items that belong to the skill page you have open.",
		position = 6
	)
	default boolean highlightPage()
	{
		return true;
	}
}

package com.skillbankorganizer;

import com.google.common.collect.ImmutableList;
import com.google.gson.Gson;
import com.google.inject.Provides;
import com.skillbankorganizer.data.BankStack;
import com.skillbankorganizer.data.Organizer;
import com.skillbankorganizer.data.SkillCatalog;
import com.skillbankorganizer.data.SkillCatalog.SkillDef;
import com.skillbankorganizer.ui.SkillBankItemOverlay;
import com.skillbankorganizer.ui.SkillBankPanel;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Skill Bank Organizer",
	description = "Scan your bank into a page per skill. Right-click Send-to-page tags the item; it never drags it for you.",
	tags = {"bank", "skills", "organizer", "skilling", "raids", "woodcutting", "magic"}
)
public class SkillBankOrganizerPlugin extends Plugin
{
	private static final BufferedImage ICON =
		ImageUtil.loadImageResource(SkillBankOrganizerPlugin.class, "/com/skillbankorganizer/icon.png");
	private static final String BANK_TAGS_GROUP = "banktags";
	private static final String ITEM_TAG_PREFIX = "item_";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SkillBankOrganizerConfig config;

	@Inject
	private Gson gson;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SpriteManager spriteManager;

	private SkillCatalog catalog;
	private SkillBankPanel panel;
	private NavigationButton navButton;
	private SkillBankItemOverlay overlay;
	// Written on the client thread by the scan, read from the Swing thread by the panel.
	private volatile List<BankStack> lastScan = ImmutableList.of();
	private volatile boolean hasScan;
	// Set from the panel on the Swing thread, read on the client thread while the overlay renders.
	private volatile String highlightedSkillId;

	@Override
	protected void startUp()
	{
		catalog = SkillCatalog.load(gson);
		panel = new SkillBankPanel(this, catalog, itemManager, spriteManager);
		overlay = new SkillBankItemOverlay(this);
		overlayManager.add(overlay);
		navButton = NavigationButton.builder()
			.tooltip("Skill Bank Organizer")
			.icon(ICON)
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		log.debug("Skill Bank Organizer started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		lastScan = ImmutableList.of();
		hasScan = false;
		highlightedSkillId = null;
		navButton = null;
		panel = null;
		overlay = null;
		log.debug("Skill Bank Organizer stopped");
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!config.autoScan())
		{
			return;
		}
		if (event.getContainerId() != InventoryID.BANK)
		{
			return;
		}
		scanContainer(event.getItemContainer());
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.rightClickSend())
		{
			return;
		}
		String option = event.getOption();
		if (option == null || (!option.startsWith("Withdraw-") && !option.startsWith("Deposit-")))
		{
			return;
		}
		int rawId = event.getItemId();
		if (rawId <= 0)
		{
			return;
		}
		int itemId = itemManager.canonicalize(rawId);
		ItemComposition composition = itemManager.getItemComposition(itemId);
		String name = composition.getName();
		if (name == null || name.equals("null"))
		{
			return;
		}
		BankStack stack = new BankStack(itemId, name, 1, 0);
		List<SkillDef> skills = Organizer.skillsFor(catalog, stack);
		if (skills.isEmpty())
		{
			SkillDef other = otherSkill();
			if (other != null)
			{
				skills = new ArrayList<>();
				skills.add(other);
			}
		}
		int shown = 0;
		for (SkillDef skill : skills)
		{
			if (shown >= 3)
			{
				break;
			}
			client.getMenu().createMenuEntry(-1)
				.setOption("Send to " + skill.name)
				.setTarget(event.getTarget())
				.setType(MenuAction.RUNELITE)
				.onClick(e -> sendToSkill(skill, itemId, name));
			shown++;
		}
	}

	public void requestScan()
	{
		clientThread.invoke(() -> scanContainer(client.getItemContainer(InventoryID.BANK)));
	}

	public void requestTagAll()
	{
		int n = 0;
		for (BankStack stack : lastScan)
		{
			for (SkillDef skill : Organizer.skillsFor(catalog, stack))
			{
				tagItem(stack.id, skill);
				n++;
			}
		}
		final int tagged = n;
		if (config.showChatScan())
		{
			clientThread.invoke(() -> client.addChatMessage(
				ChatMessageType.GAMEMESSAGE,
				"",
				"Skill Bank Organizer: tagged " + tagged + " item-skill pairs. Search #woodcutting etc. in the bank.",
				null));
		}
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setStatus("Tagged " + tagged + " entries. Search #raids, #woodcutting, …");
			}
		});
	}

	public boolean hasScan()
	{
		return hasScan;
	}

	public List<BankStack> lastScan()
	{
		return lastScan;
	}

	public SkillBankOrganizerConfig config()
	{
		return config;
	}

	public void setHighlightedSkill(String skillId)
	{
		highlightedSkillId = skillId;
	}

	public boolean shouldHighlight(int itemId)
	{
		if (!config.highlightPage() || highlightedSkillId == null || catalog == null)
		{
			return false;
		}
		int canonical = itemManager.canonicalize(itemId);
		ItemComposition composition = itemManager.getItemComposition(canonical);
		String name = composition.getName();
		if (name == null)
		{
			return false;
		}
		BankStack stack = new BankStack(canonical, name, 1, 0);
		List<SkillDef> skills = Organizer.skillsFor(catalog, stack);
		if ("OTHER".equals(highlightedSkillId))
		{
			return skills.isEmpty();
		}
		for (SkillDef skill : skills)
		{
			if (highlightedSkillId.equals(skill.id))
			{
				return true;
			}
		}
		return false;
	}

	private void sendToSkill(SkillDef skill, int itemId, String name)
	{
		if (config.tagOnSend())
		{
			tagItem(itemId, skill);
		}
		highlightedSkillId = skill.id;
		String tab = "";
		if (catalog.tabFor(skill.id) != null)
		{
			tab = " · tab " + catalog.tabFor(skill.id).id + " " + catalog.tabFor(skill.id).name;
		}
		final String message = name + " → " + skill.name + tab + ". Tagged. Drag it yourself — plugins cannot move bank items.";
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.openSkill(skill.id);
			}
		});
		log.debug("Send to {} item {}", skill.id, itemId);
	}

	private void tagItem(int itemId, SkillDef skill)
	{
		String tag = Organizer.tagName(skill);
		String key = ITEM_TAG_PREFIX + itemId;
		String current = configManager.getConfiguration(BANK_TAGS_GROUP, key);
		Set<String> tags = new LinkedHashSet<>();
		if (current != null && !current.isEmpty())
		{
			for (String part : current.split(","))
			{
				String trimmed = part.trim();
				if (!trimmed.isEmpty())
				{
					tags.add(trimmed);
				}
			}
		}
		tags.add(tag);
		configManager.setConfiguration(BANK_TAGS_GROUP, key, String.join(",", tags));
	}

	private SkillDef otherSkill()
	{
		for (SkillDef skill : catalog.skillsOrEmpty())
		{
			if ("OTHER".equals(skill.id))
			{
				return skill;
			}
		}
		return null;
	}

	private void scanContainer(ItemContainer container)
	{
		if (container == null)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.showEmpty("Open your bank, then press Scan.");
				}
			});
			return;
		}

		List<BankStack> stacks = new ArrayList<>();
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			int canonical = itemManager.canonicalize(item.getId());
			ItemComposition composition = itemManager.getItemComposition(canonical);
			String name = composition.getName();
			if (name == null || name.equals("null") || name.equals("Bank filler"))
			{
				continue;
			}
			int qty = item.getQuantity();
			if (qty <= 0 && !config.includePlaceholders())
			{
				continue;
			}
			int price = itemManager.getItemPrice(canonical);
			stacks.add(new BankStack(canonical, name, Math.max(qty, 0), price));
		}

		lastScan = ImmutableList.copyOf(stacks);
		hasScan = true;
		List<Organizer.SkillPage> pages = Organizer.build(catalog, stacks);
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.showPages(pages, stacks.size());
			}
		});

		if (config.showChatScan())
		{
			client.addChatMessage(
				ChatMessageType.GAMEMESSAGE,
				"",
				"Skill Bank Organizer: " + stacks.size() + " stacks sorted into skill pages.",
				null);
		}
		log.debug("Scanned {} bank stacks", stacks.size());
	}

	@Provides
	SkillBankOrganizerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SkillBankOrganizerConfig.class);
	}
}

package com.skillbankorganizer.data;

public final class BankStack
{
	public final int id;
	public final String name;
	public final int qty;
	public final int price;

	public BankStack(int id, String name, int qty, int price)
	{
		this.id = id;
		this.name = name == null ? "" : name;
		this.qty = qty;
		this.price = price;
	}

	public long geValue()
	{
		return (long) price * (long) qty;
	}
}

package com.skillbankorganizer.data;

import com.skillbankorganizer.data.SkillCatalog.Matcher;
import com.skillbankorganizer.data.SkillCatalog.MethodDef;
import com.skillbankorganizer.data.SkillCatalog.NeedDef;
import com.skillbankorganizer.data.SkillCatalog.SkillDef;
import com.skillbankorganizer.data.SkillCatalog.TabDef;
import com.skillbankorganizer.data.SkillCatalog.ToolDef;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public final class Organizer
{
	private Organizer()
	{
	}

	public static List<SkillPage> build(SkillCatalog catalog, List<BankStack> stacks)
	{
		List<BankStack> safe = stacks == null ? new ArrayList<>() : stacks;
		Set<Integer> claimed = new HashSet<>();
		List<SkillPage> pages = new ArrayList<>();
		SkillDef other = null;

		for (SkillDef skill : catalog.skillsOrEmpty())
		{
			if ("OTHER".equals(skill.id))
			{
				other = skill;
				continue;
			}
			pages.add(pageFor(catalog, skill, safe, claimed, false));
		}

		if (other != null)
		{
			List<BankStack> leftovers = new ArrayList<>();
			for (BankStack stack : safe)
			{
				if (!claimed.contains(stack.id))
				{
					leftovers.add(stack);
				}
			}
			pages.add(pageFor(catalog, other, leftovers, claimed, true));
		}
		return pages;
	}

	public static List<SkillDef> skillsFor(SkillCatalog catalog, BankStack stack)
	{
		List<SkillDef> hit = new ArrayList<>();
		for (SkillDef skill : catalog.skillsOrEmpty())
		{
			if ("OTHER".equals(skill.id))
			{
				continue;
			}
			if (matchesSkill(skill, stack))
			{
				hit.add(skill);
			}
		}
		return hit;
	}

	public static String tagName(SkillDef skill)
	{
		if (skill == null || skill.name == null)
		{
			return "other";
		}
		return skill.name.toLowerCase().replace(' ', '-');
	}

	private static SkillPage pageFor(SkillCatalog catalog, SkillDef skill, List<BankStack> stacks,
		Set<Integer> claimed, boolean takeAll)
	{
		List<BankStack> owned = new ArrayList<>();
		for (BankStack stack : stacks)
		{
			if (takeAll || matchesSkill(skill, stack))
			{
				owned.add(stack);
				claimed.add(stack.id);
			}
		}

		List<ToolStatus> tools = new ArrayList<>();
		if (skill.tools != null)
		{
			for (ToolDef tool : skill.tools)
			{
				BankStack hit = find(owned, tool.id, tool.name);
				if (hit == null)
				{
					hit = find(stacks, tool.id, tool.name);
				}
				tools.add(new ToolStatus(tool, hit != null, hit == null ? 0 : hit.qty, false));
			}
		}
		for (int i = tools.size() - 1; i >= 0; i--)
		{
			if (tools.get(i).owned)
			{
				tools.get(i).bestOwned = true;
				break;
			}
		}

		List<MethodStatus> methods = new ArrayList<>();
		int missing = 0;
		if (skill.methods != null)
		{
			for (MethodDef method : skill.methods)
			{
				List<NeedStatus> needs = new ArrayList<>();
				boolean ready = true;
				if (method.items != null)
				{
					for (NeedDef need : method.items)
					{
						int id = need.id == null ? -1 : need.id;
						BankStack hit = find(stacks, id, need.name);
						boolean has = hit != null;
						needs.add(new NeedStatus(need, has, hit == null ? 0 : hit.qty));
						if (!need.isOptional() && !has)
						{
							ready = false;
							missing++;
						}
					}
				}
				methods.add(new MethodStatus(method, needs, ready));
			}
		}

		Set<Integer> toolIds = new HashSet<>();
		if (skill.tools != null)
		{
			for (ToolDef tool : skill.tools)
			{
				toolIds.add(tool.id);
			}
		}
		List<BankStack> rebuild = new ArrayList<>(owned);
		rebuild.sort(Comparator
			.comparingInt((BankStack s) -> toolIds.contains(s.id) ? 0 : 1)
			.thenComparingLong(BankStack::geValue).reversed());

		TabDef tab = catalog.tabFor(skill.id);
		long ge = 0;
		int qty = 0;
		for (BankStack stack : owned)
		{
			ge += stack.geValue();
			qty += stack.qty;
		}

		return new SkillPage(skill, tab, owned, tools, methods, rebuild, missing, ge, qty);
	}

	static boolean matchesSkill(SkillDef skill, BankStack stack)
	{
		if (skill == null || skill.matchAny == null || "OTHER".equals(skill.id))
		{
			return false;
		}
		for (Matcher matcher : skill.matchAny)
		{
			if (matches(stack, matcher))
			{
				return true;
			}
		}
		return false;
	}

	static boolean matches(BankStack stack, Matcher matcher)
	{
		if (matcher == null)
		{
			return false;
		}
		String name = stack.name.toLowerCase();
		boolean idHit = matcher.ids != null && matcher.ids.contains(stack.id);
		boolean containsHit = false;
		if (matcher.nameContains != null)
		{
			for (String token : matcher.nameContains)
			{
				if (token != null && name.contains(token.toLowerCase()))
				{
					containsHit = true;
					break;
				}
			}
		}
		if (!idHit && !containsHit)
		{
			return false;
		}
		if (matcher.nameExclude != null)
		{
			for (String token : matcher.nameExclude)
			{
				if (token != null && name.contains(token.toLowerCase()))
				{
					return false;
				}
			}
		}
		return true;
	}

	static BankStack find(List<BankStack> stacks, int id, String name)
	{
		if (stacks == null)
		{
			return null;
		}
		if (id > 0)
		{
			for (BankStack stack : stacks)
			{
				if (stack.id == id)
				{
					return stack;
				}
			}
		}
		if (name == null || name.isEmpty())
		{
			return null;
		}
		String needle = name.toLowerCase();
		for (BankStack stack : stacks)
		{
			String n = stack.name.toLowerCase();
			if (n.equals(needle) || n.contains(needle))
			{
				return stack;
			}
		}
		return null;
	}

	public static final class ToolStatus
	{
		public final ToolDef tool;
		public final boolean owned;
		public final int qty;
		public boolean bestOwned;

		ToolStatus(ToolDef tool, boolean owned, int qty, boolean bestOwned)
		{
			this.tool = tool;
			this.owned = owned;
			this.qty = qty;
			this.bestOwned = bestOwned;
		}
	}

	public static final class NeedStatus
	{
		public final NeedDef need;
		public final boolean owned;
		public final int qty;

		NeedStatus(NeedDef need, boolean owned, int qty)
		{
			this.need = need;
			this.owned = owned;
			this.qty = qty;
		}
	}

	public static final class MethodStatus
	{
		public final MethodDef method;
		public final List<NeedStatus> items;
		public final boolean ready;

		MethodStatus(MethodDef method, List<NeedStatus> items, boolean ready)
		{
			this.method = method;
			this.items = items;
			this.ready = ready;
		}
	}

	public static final class SkillPage
	{
		public final SkillDef skill;
		public final TabDef tab;
		public final List<BankStack> stacks;
		public final List<ToolStatus> tools;
		public final List<MethodStatus> methods;
		public final List<BankStack> rebuild;
		public final int missingCount;
		public final long geValue;
		public final int totalQty;

		SkillPage(SkillDef skill, TabDef tab, List<BankStack> stacks, List<ToolStatus> tools,
			List<MethodStatus> methods, List<BankStack> rebuild, int missingCount, long geValue, int totalQty)
		{
			this.skill = skill;
			this.tab = tab;
			this.stacks = stacks;
			this.tools = tools;
			this.methods = methods;
			this.rebuild = rebuild;
			this.missingCount = missingCount;
			this.geValue = geValue;
			this.totalQty = totalQty;
		}

		public int stackCount()
		{
			return stacks.size();
		}
	}
}

package com.skillbankorganizer.data;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class SkillCatalog
{
	public int version;
	public List<TabDef> tabs = new ArrayList<>();
	public List<SkillDef> skills = new ArrayList<>();

	public static SkillCatalog load(Gson gson)
	{
		InputStream in = SkillCatalog.class.getResourceAsStream("/com/skillbankorganizer/skill-catalog.json");
		if (in == null)
		{
			throw new IllegalStateException("skill-catalog.json missing from plugin resources");
		}
		try (InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			SkillCatalog catalog = gson.fromJson(reader, SkillCatalog.class);
			if (catalog == null || catalog.skills == null || catalog.skills.isEmpty())
			{
				throw new IllegalStateException("skill-catalog.json did not parse");
			}
			if (catalog.tabs == null)
			{
				catalog.tabs = new ArrayList<>();
			}
			return catalog;
		}
		catch (Exception ex)
		{
			if (ex instanceof IllegalStateException)
			{
				throw (IllegalStateException) ex;
			}
			throw new IllegalStateException("Failed to read skill-catalog.json", ex);
		}
	}

	public static final class TabDef
	{
		public int id;
		public String name;
		public List<String> skills = new ArrayList<>();
	}

	public static final class SkillDef
	{
		public String id;
		public String name;
		public String rsSkill;
		public String blurb;
		public List<ToolDef> tools = new ArrayList<>();
		public List<MethodDef> methods = new ArrayList<>();
		public List<Matcher> matchAny = new ArrayList<>();
	}

	public static final class ToolDef
	{
		public int id;
		public String name;
		public int level;
	}

	public static final class MethodDef
	{
		public String name;
		public String level;
		public String why;
		public List<NeedDef> items = new ArrayList<>();
	}

	public static final class NeedDef
	{
		public Integer id;
		public String name;
		public Boolean optional;
		public String hint;

		public boolean isOptional()
		{
			return Boolean.TRUE.equals(optional);
		}
	}

	public static final class Matcher
	{
		public List<Integer> ids;
		@SerializedName("nameContains")
		public List<String> nameContains;
		@SerializedName("nameExclude")
		public List<String> nameExclude;
	}

	public TabDef tabFor(String skillId)
	{
		if (skillId == null)
		{
			return null;
		}
		for (TabDef tab : tabs)
		{
			if (tab.skills != null && tab.skills.contains(skillId))
			{
				return tab;
			}
		}
		return null;
	}

	public List<SkillDef> skillsOrEmpty()
	{
		return skills == null ? Collections.emptyList() : skills;
	}
}

package com.skillbankorganizer.data;

import com.google.common.collect.ImmutableMap;
import net.runelite.api.gameval.SpriteID;

/**
 * Maps a catalog skill id onto the game sprite the client already ships for it, so every icon in
 * the panel comes from the cache rather than from bundled artwork.
 *
 * <p>The stats tab splits its icons across two sprite sheets, and the two pages that are not real
 * skills borrow an interface icon each: Raids uses the raiding party side icon, and Uncategorized
 * uses the bank's "all items" tab icon.
 */
public final class SkillSprites
{
	/** Returned when a skill has no sprite, so callers can skip the icon instead of drawing a gap. */
	public static final int NONE = -1;

	private static final ImmutableMap<String, Integer> SPRITES = ImmutableMap.<String, Integer>builder()
		.put("ATTACK", SpriteID.Staticons.ATTACK)
		.put("STRENGTH", SpriteID.Staticons.STRENGTH)
		.put("DEFENCE", SpriteID.Staticons.DEFENCE)
		.put("RANGED", SpriteID.Staticons.RANGED)
		.put("PRAYER", SpriteID.Staticons.PRAYER)
		.put("MAGIC", SpriteID.Staticons.MAGIC)
		.put("HITPOINTS", SpriteID.Staticons.HITPOINTS)
		.put("AGILITY", SpriteID.Staticons.AGILITY)
		.put("HERBLORE", SpriteID.Staticons.HERBLORE)
		.put("THIEVING", SpriteID.Staticons.THIEVING)
		.put("CRAFTING", SpriteID.Staticons.CRAFTING)
		.put("FLETCHING", SpriteID.Staticons.FLETCHING)
		.put("MINING", SpriteID.Staticons.MINING)
		.put("SMITHING", SpriteID.Staticons.SMITHING)
		.put("FISHING", SpriteID.Staticons.FISHING)
		.put("COOKING", SpriteID.Staticons.COOKING)
		.put("FIREMAKING", SpriteID.Staticons.FIREMAKING)
		.put("WOODCUTTING", SpriteID.Staticons.WOODCUTTING)
		.put("RUNECRAFT", SpriteID.Staticons2.RUNECRAFT)
		.put("SLAYER", SpriteID.Staticons2.SLAYER)
		.put("FARMING", SpriteID.Staticons2.FARMING)
		.put("HUNTER", SpriteID.Staticons2.HUNTER)
		.put("CONSTRUCTION", SpriteID.Staticons2.CONSTRUCTION)
		.put("RAIDS", SpriteID.SideiconsInterface.RAIDING_PARTY)
		.put("OTHER", SpriteID.BanktabIcons.ALL_ITEMS)
		.build();

	private SkillSprites()
	{
	}

	/**
	 * @return the sprite id for that catalog skill, or {@link #NONE} if the catalog has grown a
	 * skill this map has not been taught yet.
	 */
	public static int spriteFor(String skillId)
	{
		if (skillId == null)
		{
			return NONE;
		}
		return SPRITES.getOrDefault(skillId, NONE);
	}
}

